  lines.push(`export const TRANSPILER_BANNER = "// Transpiled by Bun.Transpiler\\n";`);
  lines.push("");

  await mkdir("web/src/keating", { recursive: true });
  await writeFile(OUTPUT_FILE, lines.join("\n"), "utf8");

