  const jsCount = sorted.filter(([p]) => p.endsWith(".js")).length;
  console.log(`Generated ${OUTPUT_FILE} with ${sorted.length} files (${Math.round(totalBytes / 1024)} KB total, ${jsCount} JS transpiled via TypeScript)`);
